def rotate_log(logfile):
    """Rotera loggfil: log -> log.1, log.1 -> log.2 osv."""
    for i in range(4, 0, -1):
        src = f"{logfile}.{i}"
        if os.path.exists(src):
            os.rename(src, f"{logfile}.{i+1}")
    if os.path.exists(logfile):
        os.rename(logfile, f"{logfile}.1")
    Path(logfile).touch()

def compress_old(logdir):
    """Komprimera roterade filer äldre än 7 dagar."""
    now = time.time()
    for f in Path(logdir).glob("*.[0-9]*"):
        if f.suffix != ".gz" and now - f.stat().st_mtime > MAX_AGE:
            with open(f, "rb") as fin, gzip.open(f"{f}.gz", "wb") as fout:
                shutil.copyfileobj(fin, fout)
            os.remove(f)

if __name__ == "__main__":
    for log in Path(LOG_DIR).glob("*.log"):
        rotate_log(log)
    compress_old(LOG_DIR)
